### Test 4: brand-audit grep test (any test runner)

Add a simple node script tests/unit/flash-events/brand-audit.test.ts:

```ts
import { describe, it, expect } from 'vitest'
import { readFileSync } from 'fs'
import { globSync } from 'glob'

describe('Flash Events brand compliance', () => {
  const files = globSync('components/flash-events/**/*.tsx', { cwd: '/Users/yashbaldha/Desktop/Boldteq App/InkOS' })

  it('no raw hex literals (except brand-config sites)', () => {
    for (const file of files) {
      const content = readFileSync(file, 'utf-8')
      const matches = content.match(/#[0-9a-fA-F]{3,6}\b/g) ?? []
      // brand colors allowed: #F7F7F5, #0F0F0F (Bone, Onyx) inside QR config
      const offenders = matches.filter(m => !['#F7F7F5', '#0F0F0F'].includes(m.toUpperCase().replace(/^#/, '#').toLowerCase() === '#f7f7f5' ? '#F7F7F5' : m.toUpperCase()))
      // simpler: just allow these two
      const filtered = matches.filter(m => !/^#(F7F7F5|0F0F0F)$/i.test(m))
      expect(filtered, `${file} contains raw hex: ${filtered.join(', ')}`).toEqual([])
    }
  })

  it('no default Tailwind shadows (shadow-md, shadow-lg, shadow-xl)', () => {
    for (const file of files) {
      const content = readFileSync(file, 'utf-8')
      expect(content, `${file} uses forbidden shadow class`).not.toMatch(/\bshadow-(?:md|lg|xl|2xl)\b/)
    }
  })
})
```

(Adjust glob path import — Vitest supports `glob` package; if not installed, use `fast-glob` or `node:fs.readdirSync` recursive.)

### Test 5: tests/unit/flash-events/feature-gate.test.ts

Vitest unit test asserting `flash_events` is in `KNOWN_FEATURE_KEYS` with min plan `studio`:

