  it('is available on studio, pro, enterprise plans', () => {
    expect(hasFeature('studio', 'flash_events')).toBe(true)
    expect(hasFeature('pro', 'flash_events')).toBe(true)
    expect(hasFeature('enterprise', 'flash_events')).toBe(true)
  })
})
```

